// Parse MCP tool call from AI agent
// Input: { tool_name: string, arguments: object } or JSON string
const raw = $input.item.json;

let toolName, args;
try {
  // Handle various input formats from toolWorkflow
  let data = raw;

  // If input is a string, parse it
  if (typeof raw === 'string') {
    data = JSON.parse(raw);
  }

  // Try direct fields first
  toolName = data.tool_name || data.toolName || data.name;
  args = data.arguments || data.args || data.params || {};

  // If no tool_name found, check nested 'query' field (toolWorkflow sends query)
  if (!toolName && data.query) {
    const q = typeof data.query === 'string' ? JSON.parse(data.query) : data.query;
    toolName = q.tool_name || q.toolName || q.name;
    args = q.arguments || q.args || q.params || {};
  }

  // If arguments is still a string, try parsing it
  if (typeof args === 'string') {
    try { args = JSON.parse(args); } catch { args = { query: args }; }
  }
} catch (e) {
  return {
    json: {
      error: true,
      message: 'Invalid input. Expected JSON with tool_name and arguments. Error: ' + e.message,
      raw: JSON.stringify(raw).substring(0, 500)
    }
  };
}

if (!toolName) {
  return {
    json: {
      error: true,
      message: 'Missing tool_name. Available tools: search_knowledge, get_expert_rule, get_expertise_areas, match_experts, get_agent_knowledge, get_project_context, search_knowledge_v2, get_knowledge_item, get_knowledge_stats, get_story_context, create_story_ruleset, generate_copilot_instructions, route_task, compose_context, validate_compliance, moderate_flow, evaluate_tests, assess_quality, suggest_next_step, estimate_effort, check_pr_compliance, transition_delivery_status, get_delivery_timeline, get_allowed_transitions, manage_story_environment, get_story_environments',
      raw: JSON.stringify(raw).substring(0, 500)
    }
  };
}

// Build JSON-RPC 2.0 payload
const rpcPayload = {
  jsonrpc: '2.0',
  id: Date.now(),
  method: 'tools/call',
  params: {
    name: toolName,
    arguments: args
  }
};

return {
  json: {
    toolName,
    args,
    rpcBody: JSON.stringify(rpcPayload)
  }
};

// Format MCP JSON-RPC response for AI agent consumption
const response = $input.item.json;
const toolName = $('Parse MCP Call').item.json.toolName;

// Handle error in Parse stage
if ($('Parse MCP Call').item.json.error) {
  return { json: { response: $('Parse MCP Call').item.json.message } };
}

// Handle HTTP/network errors
if (!response || typeof response !== 'object') {
  return { json: { response: 'MCP server returned invalid response: ' + JSON.stringify(response).substring(0, 500) } };
}

// Handle JSON-RPC error
if (response.error) {
  const errMsg = typeof response.error === 'object' 
    ? (response.error.message || JSON.stringify(response.error))
    : String(response.error);
  return { json: { response: `MCP Error calling ${toolName}: ${errMsg}` } };
}

// Extract content from successful result
const result = response.result;
if (result && Array.isArray(result.content)) {
  const text = result.content
    .map(c => {
      if (c.type === 'text') return c.text;
      return JSON.stringify(c);
    })
    .join('\n');
  return { json: { response: text } };
}

// Fallback: stringify the result
return { json: { response: JSON.stringify(result || response) } };
